def prepare(df, cat_cols, num_cols):
    out = df.copy()

    for c in cat_cols:
        if c not in out.columns:
            out[c] = "unknown"
        out[c] = out[c].astype(str)

    for c in num_cols:
        if c not in out.columns:
            out[c] = np.nan
        out[c] = pd.to_numeric(out[c], errors="coerce").astype(np.float32)
